from pathlib import Path

from atlas.plan_parser import parse_plan, _slug, _looks_runnable


SAMPLE_PLAN = """# Plan: Add /healthz Endpoint

**Generated by**: Coeus

## Objective

Add a `/healthz` endpoint to the FastAPI app that returns `{"status": "ok"}` with HTTP 200.

## Phases

### Phase 1 — Add the endpoint

Edit `app/main.py` to add a GET handler at `/healthz`.

**Steps:**
1. Open `app/main.py`
2. Add `@app.get("/healthz")` handler returning `{"status": "ok"}`
3. Save the file

**Verification:**
- Run `pytest tests/test_health.py -v` and confirm it passes
- Manual: hit the endpoint with `curl http://localhost:8000/healthz`

**Deliverable:** A working `/healthz` endpoint returning the expected JSON.

### Phase 2 — Add a test

Create `tests/test_health.py` with a test that asserts 200 + correct JSON.

**Steps:**
1. Create the test file
2. Use FastAPI TestClient
3. Assert response.status_code == 200 and response.json() == {"status": "ok"}

**Verification:**
- `pytest tests/test_health.py -v`
- `ruff check tests/test_health.py`

**Deliverable:** Passing test file at `tests/test_health.py`.
"""


def test_parses_objective_and_phases(tmp_path: Path) -> None:
    plan = tmp_path / "plan.md"
    plan.write_text(SAMPLE_PLAN)
    objective, tasks = parse_plan(plan)

    assert "/healthz" in objective
    assert len(tasks) == 2

    t1 = tasks[0]
    assert t1.phase == "Phase 1"
    assert "endpoint" in t1.title.lower()
    assert t1.id.startswith("phase-1-")
    assert any("app/main.py" in s for s in t1.steps)
    assert "/healthz" in t1.deliverable
    assert any("pytest" in v.command for v in t1.verifications)

    t2 = tasks[1]
    assert t2.phase == "Phase 2"
    cmds = [v.command for v in t2.verifications if v.command]
    assert any("pytest" in c for c in cmds)
    assert any("ruff" in c for c in cmds)


def test_slug() -> None:
    assert _slug("Add the endpoint") == "add-the-endpoint"
    assert _slug("Hello, World!!") == "hello-world"
    s = _slug("a" * 200)
    assert len(s) <= 40


def test_looks_runnable() -> None:
    assert _looks_runnable("pytest tests/ -v")
    assert _looks_runnable("ruff check .")
    assert _looks_runnable("./scripts/build.sh")
    assert not _looks_runnable("Confirm by visual inspection")
    assert not _looks_runnable("status: ok")
    assert not _looks_runnable("")


def test_empty_plan_returns_no_tasks(tmp_path: Path) -> None:
    plan = tmp_path / "empty.md"
    plan.write_text("# Plan: Nothing\n\n## Objective\n\nTBD\n")
    objective, tasks = parse_plan(plan)
    assert "TBD" in objective
    assert tasks == []
